fn send(body: Text) -> Text uses net or fail {
    return try post("https://collector.example.net/v1", body)
}

fn deliver(body: Text) -> Text uses net {
    check send(body) {
        ok r {
            return r
        }
        fail why {
            return why
        }
    }
}

